import{_ as t,b as a,c as i,g as o}from"./chunks/framework.86O3EbG5.js";const f=JSON.parse('{"title":"弱者的武器","description":"","frontmatter":{"title":"弱者的武器","author":"oasis","date":"2026-03-22T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/weapons-of-the-weak/1.md","filePath":"articles/books/weapons-of-the-weak/1.md"}'),l={name:"articles/books/weapons-of-the-weak/1.md"};function s(_,e,r,n,p,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<p>《弱者的武器》聚焦于农民运动与乡村社会反抗的研究。作者詹姆斯·C·斯科特通过民族志方法呈现了东南亚农民在面对外来霸权时，采取日常且隐蔽的反抗形式，揭示了被压迫者如何在看似顺从的表象下维护自身利益和文化完整。这本书的主题可以概括为：研究农民（尤其是东南亚农民）在殖民或国家压迫下的隐性抵抗与生存策略。</p><p>詹姆斯·C·斯科特在书中把农民的隐性抵抗与生存策略概括为一套「日常的、匿名的、小规模」的行动体系，核心可归结为两大类。</p><h2 id="_1-躲避型-个人—家庭层面的生存伦理" tabindex="-1">1. 躲避型（个人—家庭层面的生存伦理）</h2><ul><li>偷懒、装糊涂、假装顺从，以减少被榨取的劳动和税赋负担。</li><li>逃避兵役、逃荒、流动打工，用「离场」降低被控制的风险。</li><li>以「损人利己」方式保存自身：从自己或同伴处偷取粮食、高价转租土地以求活命。</li></ul><h2 id="_2-消耗型-社区—村落层面的弱者武器" tabindex="-1">2. 消耗型（社区—村落层面的弱者武器）</h2><ul><li>集体性的怠工、破坏、纵火、暗中破坏，通过日常的小破坏削弱统治者可抽取的产出。</li><li>口头上的诽谤、流言、嘲讽，用「隐藏的文本」在背后解构权威话语。</li><li>利用传统习俗、地方性网络进行非正式互助，抵消国家与地主的政策压力。</li></ul><p>这些策略之所以有效，源于农民分散、缺乏组织的处境：它们无需事先协调、没有旗帜口号，却能因广泛参与而积少成多，最终让国家或地主的政策陷入混乱，被迫让步或调整。换言之，偷懒、逃避与破坏既是生存手段，也是对霸权的隐性抵抗；它们构成了「弱者的武器」，使被压迫者在不直接挑战权威的前提下维护自身生计与文化。</p>',7)])])}const h=t(l,[["render",s]]);export{f as __pageData,h as default};
